package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import lombok.*;
@Entity(name="JourneyFinalReportVersion") @Table(name="final_report_versions") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyFinalReportVersion extends BaseEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="report_id",nullable=false)private JourneyFinalReport report;@Column(nullable=false)private int versionNumber;@Column(name="content_json",nullable=false,columnDefinition="TEXT")private String contentJson;public static JourneyFinalReportVersion create(Project p,ConceptVersion c,JourneyFinalReport r,String content){JourneyFinalReportVersion v=new JourneyFinalReportVersion();v.project=p;v.conceptVersion=c;v.report=r;v.versionNumber=1;v.contentJson=content;return v;}}
